<?php
 namespace Slim; class Environment implements \ArrayAccess, \IteratorAggregate { protected $properties; protected static $environment; public static function getInstance($refresh = false) { if (is_null(self::$environment) || $refresh) { self::$environment = new self(); } return self::$environment; } public static function mock($userSettings = array()) { $defaults = array( 'REQUEST_METHOD' => 'GET', 'SCRIPT_NAME' => '', 'PATH_INFO' => '', 'QUERY_STRING' => '', 'SERVER_NAME' => 'localhost', 'SERVER_PORT' => 80, 'ACCEPT' => 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8', 'ACCEPT_LANGUAGE' => 'en-US,en;q=0.8', 'ACCEPT_CHARSET' => 'ISO-8859-1,utf-8;q=0.7,*;q=0.3', 'USER_AGENT' => 'Slim Framework', 'REMOTE_ADDR' => '127.0.0.1', 'slim.url_scheme' => 'http', 'slim.input' => '', 'slim.errors' => @fopen('php://stderr', 'w') ); self::$environment = new self(array_merge($defaults, $userSettings)); return self::$environment; } private function __construct($settings = null) { if ($settings) { $this->properties = $settings; } else { $env = array(); $env['REQUEST_METHOD'] = $_SERVER['REQUEST_METHOD']; $env['REMOTE_ADDR'] = $_SERVER['REMOTE_ADDR']; $scriptName = $_SERVER['SCRIPT_NAME']; $requestUri = $_SERVER['REQUEST_URI']; $queryString = isset($_SERVER['QUERY_STRING']) ? $_SERVER['QUERY_STRING'] : ''; if (safe_strpos($requestUri, $scriptName) !== false) { $physicalPath = $scriptName; } else { $physicalPath = str_replace('\\', '', dirname($scriptName)); } $env['SCRIPT_NAME'] = rtrim($physicalPath, '/'); $env['PATH_INFO'] = $requestUri; if (substr($requestUri, 0, safe_strlen($physicalPath)) == $physicalPath) { $env['PATH_INFO'] = substr($requestUri, safe_strlen($physicalPath)); } $env['PATH_INFO'] = str_replace('?' . $queryString, '', $env['PATH_INFO']); $env['PATH_INFO'] = '/' . ltrim($env['PATH_INFO'], '/'); $env['QUERY_STRING'] = $queryString; $env['SERVER_NAME'] = $_SERVER['SERVER_NAME']; $env['SERVER_PORT'] = isset($_SERVER['SERVER_PORT']) ? $_SERVER['SERVER_PORT'] : 80; $headers = \Slim\Http\Headers::extract($_SERVER); foreach ($headers as $key => $value) { $env[$key] = $value; } $env['slim.url_scheme'] = empty($_SERVER['HTTPS']) || $_SERVER['HTTPS'] === 'off' ? 'http' : 'https'; $rawInput = @file_get_contents('php://input'); if (!$rawInput) { $rawInput = ''; } $env['slim.input'] = $rawInput; $env['slim.errors'] = @fopen('php://stderr', 'w'); $this->properties = $env; } } public function offsetExists($offset) { return isset($this->properties[$offset]); } public function offsetGet($offset) { if (isset($this->properties[$offset])) { return $this->properties[$offset]; } return null; } public function offsetSet($offset, $value) { $this->properties[$offset] = $value; } public function offsetUnset($offset) { unset($this->properties[$offset]); } public function getIterator() { return new \ArrayIterator($this->properties); } } 